export class LWWElementSet<T> {
  private addSet = new Map<string, { value: T; timestamp: number }>();
  private removeSet = new Map<string, number>();

  public add(id: string, value: T, timestamp: number): void {
    const existing = this.addSet.get(id);
    if (!existing || timestamp > existing.timestamp) {
      this.addSet.set(id, { value, timestamp });
    }
  }

  public remove(id: string, timestamp: number): void {
    const existing = this.removeSet.get(id) || 0;
    if (timestamp > existing) {
      this.removeSet.set(id, timestamp);
    }
  }
}
